@Component("offer-handler")
@ProcessingGroup("offer-processing-group")
public class OfferEventHandler {
	
	// core constructor
	OfferEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateOfferEvent
     */
    @EventHandler
    public void handle( CreateOfferEvent event) {
        entityManager.persist(new Offer(event.getOfferId(), event.getOfferNumber(), event.getProposedStartDate(), event.getBaseSalary(), event.getSignOnBonus(), event.getRequisition(), event.getCandidate(), event.getApprovedBy(), event.getContract(), event.getStatus()));
    }

    /*
     * @param	event UpdateOfferEvent
     */
    @EventHandler
    public Offer handle( UpdateOfferEvent event) {
    	entityManager.merge(new Offer(event.getOfferId(), event.getOfferNumber(), event.getProposedStartDate(), event.getBaseSalary(), event.getSignOnBonus(), event.getRequisition(), event.getCandidate(), event.getApprovedBy(), event.getContract(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteOfferEvent
     */
    @EventHandler
    public void on( DeleteOfferEvent event) {
    	Offer entity = new Offer();
   
    	// ------------------------------------------
    	// apply the OfferId
    	// ------------------------------------------
    	entity.setOfferId( event.getOfferId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final OfferRepository offerEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(OfferEventHandler.class.getName());

}
